List<Employee> sortAndFilter(List<Employee> all, String department, Double minSalary, String sort) {
    List<Employee> result = all.stream()
        .filter(e -> department == null || e.department().equals(department))     // rownosc
        .filter(e -> minSalary == null || e.salary() >= minSalary)                 // porownanie
        .collect(Collectors.toList());

    if (sort != null && sort.startsWith("-")) {
        String field = sort.substring(1);
        result.sort(Comparator.comparingDouble(Employee::salary).reversed()); // MALEJACO
    } else if ("salary".equals(sort)) {
        result.sort(Comparator.comparingDouble(Employee::salary)); // ROSNACO
    }
    return result;
}

// ZLE: stronicowanie PRZED filtrowaniem - bledny wynik
List<Employee> wrongOrder(List<Employee> all, String department, int offset, int limit) {
    List<Employee> page = all.stream().skip(offset).limit(limit).toList(); // stronicuj NAJPIERW
    return page.stream().filter(e -> e.department().equals(department)).toList(); // filtruj POTEM
    // Wynik moze zawierac 0 elementow, mimo ze w calej kolekcji jest wielu pasujacych!
}

// DOBRZE: filtruj -> sortuj -> stronicuj, w tej kolejnosci
List<Employee> rightOrder(List<Employee> all, String department, int offset, int limit) {
    List<Employee> filtered = all.stream()
        .filter(e -> e.department().equals(department)) // 1. FILTRUJ
        .sorted(Comparator.comparing(Employee::name))     // 2. SORTUJ
        .toList();
    return filtered.stream().skip(offset).limit(limit).toList(); // 3. STRONICUJ na koncu
}
